/// Motion tokens. Springs are converted from tension/friction to SwiftUI interpolating springs.
enum FieldMotion {
    enum Duration {
        static let instant: Double = 0.04
        static let xs: Double = 0.1
        static let sm: Double = 0.16
        static let base: Double = 0.2
        static let recede: Double = 0.18
        static let emphasized: Double = 0.22
        static let lg: Double = 0.26
        static let xl: Double = 0.32
    }
    enum Delay {
        static let stagger: Double = 0.025
        static let beat: Double = 0.12
    }
    enum Easing {
        static func standard(_ duration: Double) -> Animation { .timingCurve(0.32, 0.72, 0, 1, duration: duration) }
        static func loft(_ duration: Double) -> Animation { .timingCurve(0.22, 1, 0.36, 1, duration: duration) }
        static func accelerate(_ duration: Double) -> Animation { .timingCurve(0.4, 0, 1, 1, duration: duration) }
        static func decelerate(_ duration: Double) -> Animation { .timingCurve(0, 0, 0.2, 1, duration: duration) }
        static func easeInOut(_ duration: Double) -> Animation { .timingCurve(0.6, 0, 0.4, 1, duration: duration) }
    }
    enum Spring {
        static let interaction = Animation.interpolatingSpring(mass: 1, stiffness: 220, damping: 18)
        static let snappy = Animation.interpolatingSpring(mass: 1, stiffness: 280, damping: 22)
        static let springLight = Animation.interpolatingSpring(mass: 1, stiffness: 300, damping: 28)
        static let springHeavy = Animation.interpolatingSpring(mass: 1, stiffness: 320, damping: 32)
        static let springBouncy = Animation.interpolatingSpring(mass: 1, stiffness: 280, damping: 18)
    }
}
